 int primary;LinearLayout root;boolean ar(){return AppSettings.isArabic(this);}String tr(String a,String e){return AppSettings.tr(this,a,e);}int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}TextView t(String x,int z,boolean b){TextView v=new TextView(this);v.setText(x);v.setTextSize(z);if(b)v.setTypeface(null,1);return v;}
 @Override public void onCreate(Bundle b){super.onCreate(b);V4Theme.apply(this);primary=V4Theme.primary(this);getWindow().setStatusBarColor(primary);ScrollView s=new ScrollView(this);s.setBackgroundColor(Color.rgb(244,247,249));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(14),dp(14),dp(28));root.setLayoutDirection(ar()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);s.addView(root);LinearLayout hero=new LinearLayout(this);hero.setOrientation(LinearLayout.VERTICAL);hero.setPadding(dp(18),dp(16),dp(18),dp(18));hero.setBackground(bg(primary,24));TextView h=t(tr("مركز مناسبـاتي v4","Munasabati v4 Center"),27,true);h.setTextColor(Color.WHITE);hero.addView(h);TextView sub=t(tr("الصحة • الإحصائيات • البحث • الخريطة • الخصوصية • الأدوات","Health • Dashboard • Search • Map • Privacy • Tools"),12,false);sub.setTextColor(Color.rgb(225,240,238));hero.addView(sub);root.addView(hero,p(-1,-2,0,0,0,dp(12)));add("🩺",tr("تشخيص وصحة التطبيق","App health & diagnostics"),this::health);add("📊",tr("Dashboard الإحصائيات","Statistics dashboard"),this::dashboard);add("🔎",tr("البحث الذكي","Smart search"),this::smartSearch);add("🗺",tr("خريطة المناسبات","Events map"),this::map);add("🗑",tr("سلة المحذوفات — 30 يومًا","Trash — 30 days"),this::trash);add("🕘",tr("سجل التعديلات History","Event history"),this::history);add("🎨",tr("الثيمات والمظهر","Themes & appearance"),this::themes);add("🔐",tr("قفل التطبيق والخصوصية","App lock & privacy"),this::security);add("↗",tr("المشاركة المتقدمة","Advanced event sharing"),this::share);add("▦",tr("Widgets إضافية","Extra widgets"),this::widgets);setContentView(s);}
 void add(String icon,String label,Runnable r){Button b=new Button(this);b.setAllCaps(false);b.setText(icon+"   "+label);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setTextSize(16);b.setTextColor(Color.rgb(31,42,55));b.setBackground(bg(Color.WHITE,17));LinearLayout.LayoutParams p=p(-1,dp(58),0,0,0,dp(8));root.addView(b,p);b.setOnClickListener(v->r.run());}
