 void health(){boolean notif=Build.VERSION.SDK_INT<33||checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED;boolean full=StrongAlertSupport.canUseFullScreen(this);PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);boolean battery=pm.isIgnoringBatteryOptimizations(getPackageName());boolean cal=CalendarIntegration.enabled(this)&&CalendarIntegration.hasPermission(this)&&CalendarIntegration.selectedCalendarId(this)>0;long backup=AppSettings.lastBackupTime(this);long widget=getSharedPreferences("munasabati_v4",0).getLong("widget_last_update",0);JSONArray er=V4Log.errors(this);StringBuilder s=new StringBuilder();s.append(notif?"✅ ":"❌ ").append(tr("الإشعارات تعمل","Notifications allowed")).append("\n").append(full?"✅ ":"⚠️ ").append(tr("التنبيه القوي مسموح","Strong Alert full-screen permission")).append("\n").append(battery?"✅ ":"⚠️ ").append(tr("البطارية لا تقيّد التطبيق","Battery background exemption")).append("\n").append(cal?"✅ ":"⚠️ ").append(tr("Google/Outlook Sync: ","Google/Outlook Sync: ")).append(CalendarIntegration.selectedCalendarLabel(this)).append("\n").append("☁ ").append(tr("آخر Backup: ","Last backup: ")).append(fmt(backup)).append("\n").append("▦ ").append(tr("آخر تحديث Widget: ","Last widget update: ")).append(fmt(widget)).append("\n\n").append(tr("آخر الأخطاء:","Recent errors:"));for(int i=0;i<Math.min(8,er.length());i++){JSONObject o=er.optJSONObject(i);if(o!=null)s.append("\n• ").append(o.optString("type")).append(": ").append(o.optString("message"));}new AlertDialog.Builder(this).setTitle(tr("صحة التطبيق","App health")).setMessage(s.toString()).setNegativeButton(tr("إغلاق","Close"),null).setNeutralButton(tr("إعدادات البطارية","Battery settings"),(d,w)->{try{startActivity(new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:"+getPackageName())));}catch(Exception ignored){}}).setPositiveButton(tr("مسح سجل الأخطاء","Clear errors"),(d,w)->V4Log.clearErrors(this)).show();}
 void dashboard(){List<EventStore.Event> es=EventStore.load(this);long now=System.currentTimeMillis();Calendar n=Calendar.getInstance(),start=(Calendar)n.clone();start.set(Calendar.DAY_OF_MONTH,1);start.set(Calendar.HOUR_OF_DAY,0);start.set(Calendar.MINUTE,0);Calendar end=(Calendar)start.clone();end.add(Calendar.MONTH,1);int month=0,up=0,sync=0,strong=0;HashMap<String,Integer> cats=new HashMap<>();int[] months=new int[12];for(EventStore.Event e:es){long tt=Recurrence.isRecurring(e)?Recurrence.nextOccurrence(e,now):e.eventTime;if(tt>=start.getTimeInMillis()&&tt<end.getTimeInMillis())month++;if(tt>=now)up++;if(e.calendarSync)sync++;if(e.strongAlert)strong++;cats.put(e.category,cats.getOrDefault(e.category,0)+1);Calendar c=Calendar.getInstance();c.setTimeInMillis(e.eventTime);months[c.get(Calendar.MONTH)]++;}String top="—";int max=0;for(Map.Entry<String,Integer>x:cats.entrySet())if(x.getValue()>max){max=x.getValue();top=Categories.label(this,x.getKey());}StringBuilder b=new StringBuilder();b.append(tr("هذا الشهر: ","This month: ")).append(month).append("\n").append(tr("القادمة: ","Upcoming: ")).append(up).append("\n").append(tr("أكثر فئة: ","Top category: ")).append(top).append("\n").append(tr("المتزامنة: ","Synced: ")).append(sync).append("\n").append(tr("التنبيه القوي: ","Strong alerts: ")).append(strong).append("\n\n").append(tr("التوزيع حسب الشهر","Monthly distribution")).append("\n");for(int i=0;i<12;i++){b.append(i+1).append(": ");for(int k=0;k<Math.min(20,months[i]);k++)b.append("▮");b.append(" ").append(months[i]).append("\n");}new AlertDialog.Builder(this).setTitle("Dashboard").setMessage(b.toString()).setPositiveButton("OK",null).show();}
 void smartSearch(){EditText q=new EditText(this);q.setHint(tr("مثال: أعياد الميلاد القادمة أو مناسبات سبتمبر أو الرياض","Example: upcoming birthdays, September events, Riyadh"));new AlertDialog.Builder(this).setTitle(tr("البحث الذكي","Smart search")).setView(q).setNegativeButton(tr("إلغاء","Cancel"),null).setPositiveButton(tr("بحث","Search"),(d,w)->showSearch(q.getText().toString())).show();}
 void showSearch(String q){String x=q.toLowerCase(Locale.ROOT);ArrayList<EventStore.Event> out=new ArrayList<>();int wantedMonth=monthFromText(x);for(EventStore.Event e:EventStore.load(this)){boolean ok=true;if((x.contains("ميلاد")||x.contains("birthday"))&&!"birthday".equals(e.category))ok=false;if((x.contains("متزام")||x.contains("google")||x.contains("outlook")||x.contains("sync"))&&!e.calendarSync)ok=false;if((x.contains("رياض")||x.contains("riyadh"))&&!(e.locationName.toLowerCase().contains("رياض")||e.locationName.toLowerCase().contains("riyadh")))ok=false;if(wantedMonth>=0){Calendar c=Calendar.getInstance();c.setTimeInMillis(e.eventTime);if(c.get(Calendar.MONTH)!=wantedMonth)ok=false;}if(x.contains("قادم")||x.contains("upcoming")){long tt=Recurrence.isRecurring(e)?Recurrence.nextOccurrence(e,System.currentTimeMillis()):e.eventTime;if(tt<System.currentTimeMillis())ok=false;}V4Meta.Meta m=V4Meta.get(this,e.id);if(x.contains("العائلة")&&!"family".equals(m.tag))ok=false;if(x.contains("العمل")&&!"work".equals(m.tag))ok=false;if(ok&&(x.trim().isEmpty()||x.contains("ميلاد")||x.contains("birthday")||x.contains("قادم")||x.contains("upcoming")||wantedMonth>=0||x.contains("رياض")||x.contains("sync")||x.contains("google")||x.contains("outlook")||e.title.toLowerCase().contains(x)))out.add(e);}chooseEvent(out,tr("نتائج البحث","Search results"),e->startActivity(new Intent(this,EditEventActivity.class).putExtra("event_id",e.id)));}
 int monthFromText(String x){String[][] n={{"يناير","january"},{"فبراير","february"},{"مارس","march"},{"أبريل","april"},{"مايو","may"},{"يونيو","june"},{"يوليو","july"},{"أغسطس","august"},{"سبتمبر","september"},{"أكتوبر","october"},{"نوفمبر","november"},{"ديسمبر","december"}};for(int i=0;i<12;i++)for(String s:n[i])if(x.contains(s))return i;return-1;}
 void map(){ArrayList<EventStore.Event> es=new ArrayList<>();for(EventStore.Event e:EventStore.load(this))if(parseGeo(e.locationUrl)!=null)es.add(e);if(es.isEmpty()){toast(tr("لا توجد مناسبات بموقع جغرافي من نوع geo بعد.","No events with geo locations yet."));return;}WebView w=new WebView(this);w.getSettings().setJavaScriptEnabled(true);StringBuilder markers=new StringBuilder();for(EventStore.Event e:es){double[] xy=parseGeo(e.locationUrl);markers.append("L.marker([").append(xy[0]).append(',').append(xy[1]).append("]).addTo(map).bindPopup('").append(js(e.title)).append("');");}double[] first=parseGeo(es.get(0).locationUrl);String html="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><link rel='stylesheet' href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'/><script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'></script></head><body style='margin:0'><div id='m' style='height:100vh'></div><script>var map=L.map('m').setView(["+first[0]+","+first[1]+"],10);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png').addTo(map);"+markers+"</script></body></html>";w.loadDataWithBaseURL("https://openstreetmap.org",html,"text/html","UTF-8",null);new AlertDialog.Builder(this).setTitle(tr("خريطة المناسبات","Events map")).setView(w).setPositiveButton(tr("إغلاق","Close"),null).show();}
 void trash(){JSONArray a=TrashStore.items(this);if(a.length()==0){toast(tr("سلة المحذوفات فارغة","Trash is empty"));return;}String[] labels=new String[a.length()];for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i),e=o==null?null:o.optJSONObject("event");labels[i]=(e==null?"?":e.optString("title"))+" • "+fmt(o==null?0:o.optLong("deletedAt"));}new AlertDialog.Builder(this).setTitle(tr("سلة المحذوفات","Trash")).setItems(labels,(d,which)->new AlertDialog.Builder(this).setTitle(labels[which]).setNegativeButton(tr("حذف نهائي","Delete permanently"),(x,y)->TrashStore.removeAt(this,which)).setPositiveButton(tr("استعادة","Restore"),(x,y)->{TrashStore.restore(this,which);toast(tr("تمت الاستعادة","Restored"));}).show()).setPositiveButton(tr("إغلاق","Close"),null).show();}
 void history(){JSONArray a=V4Log.history(this,0);StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(40,a.length());i++){JSONObject o=a.optJSONObject(i);if(o!=null)b.append(fmt(o.optLong("time"))).append(" • #").append(o.optLong("eventId")).append(" • ").append(o.optString("type")).append("\n").append(o.optString("message")).append("\n\n");}new AlertDialog.Builder(this).setTitle(tr("سجل التعديلات","History")).setMessage(b.length()==0?tr("لا يوجد سجل بعد","No history yet"):b.toString()).setPositiveButton("OK",null).show();}
 void themes(){String[] a=ar()?new String[]{"تلقائي حسب النظام","الوضع الفاتح","الوضع الداكن","أخضر مناسبـاتي","ذهبي Premium","أزرق","بنفسجي","Dynamic Color"}:new String[]{"System","Light","Dark","Munasabati green","Premium gold","Blue","Purple","Dynamic Color"};new AlertDialog.Builder(this).setTitle(tr("الثيم والمظهر","Theme & appearance")).setItems(a,(d,i)->{if(i==0)V4Theme.setMode(this,"system");else if(i==1)V4Theme.setMode(this,"light");else if(i==2)V4Theme.setMode(this,"dark");else if(i==3){V4Theme.setDynamic(this,false);V4Theme.setPrimary(this,"#195B56");}else if(i==4){V4Theme.setDynamic(this,false);V4Theme.setPrimary(this,"#D09738");}else if(i==5){V4Theme.setDynamic(this,false);V4Theme.setPrimary(this,"#3B82F6");}else if(i==6){V4Theme.setDynamic(this,false);V4Theme.setPrimary(this,"#8B5CF6");}else{V4Theme.setDynamic(this,true);}recreate();}).show();}
 void security(){boolean enabled=getSharedPreferences("munasabati_v4",0).getBoolean("lock_enabled",false);if(enabled){new AlertDialog.Builder(this).setTitle(tr("قفل التطبيق مفعّل","App lock enabled")).setMessage(tr("يستخدم البصمة/الوجه عند توفرها مع PIN احتياطي.","Uses fingerprint/face when available with PIN fallback.")).setNegativeButton(tr("إلغاء","Cancel"),null).setPositiveButton(tr("إيقاف القفل","Disable lock"),(d,w)->getSharedPreferences("munasabati_v4",0).edit().putBoolean("lock_enabled",false).apply()).show();return;}EditText p=new EditText(this);p.setInputType(2);p.setHint("PIN (4–8)");new AlertDialog.Builder(this).setTitle(tr("تفعيل قفل التطبيق","Enable app lock")).setMessage(tr("سيتم استخدام البصمة أو الوجه أولًا، وPIN كخيار احتياطي.","Fingerprint/face will be used first, with PIN as fallback.")).setView(p).setNegativeButton(tr("إلغاء","Cancel"),null).setPositiveButton(tr("تفعيل","Enable"),(d,w)->{String pin=p.getText().toString();if(pin.length()>=4)getSharedPreferences("munasabati_v4",0).edit().putBoolean("lock_enabled",true).putString("pin_hash",LauncherActivity.hash(pin)).apply();else toast(tr("PIN قصير؛ استخدم 4 أرقام على الأقل","PIN too short; use at least 4 digits"));}).show();}
 void share(){chooseEvent(EventStore.load(this),tr("اختر مناسبة للمشاركة","Choose event to share"),e->{String[] a=ar()?new String[]{"نص منسق","بطاقة صورة","QR Code","ملف Calendar .ics"}:new String[]{"Formatted text","Image card","QR Code","Calendar .ics"};new AlertDialog.Builder(this).setTitle(e.title).setItems(a,(d,i)->{if(i==0){Intent x=new Intent(Intent.ACTION_SEND);x.setType("text/plain");x.putExtra(Intent.EXTRA_TEXT,V4Share.text(this,e));startActivity(Intent.createChooser(x,tr("مشاركة","Share")));}else if(i==1)V4Share.shareCard(this,e);else if(i==2)V4Share.shareQr(this,e);else V4Share.shareIcs(this,e);}).show();});}
 void widgets(){String msg=tr("أضيفت ثلاثة Widgets جديدة:\n• مصغر لمناسبة واحدة\n• Countdown كبير\n• تقويم شهري\n\nأضفها من شاشة الهاتف: ضغط مطول ← Widgets ← مناسبـاتي.","Three extra widgets are included:\n• Single-event mini widget\n• Large countdown widget\n• Monthly calendar widget\n\nAdd them from Home screen: long press → Widgets → Munasabati.");new AlertDialog.Builder(this).setTitle(tr("Widgets إضافية","Extra widgets")).setMessage(msg).setPositiveButton("OK",null).show();}
 interface Pick{void go(EventStore.Event e);}void chooseEvent(List<EventStore.Event> es,String title,Pick p){if(es==null||es.isEmpty()){toast(tr("لا توجد مناسبات","No events"));return;}String[] a=new String[es.size()];for(int i=0;i<a.length;i++)a[i]=Categories.icon(es.get(i).category)+" "+es.get(i).title;new AlertDialog.Builder(this).setTitle(title).setItems(a,(d,i)->p.go(es.get(i))).show();}
 String fmt(long t){return t<=0?"—":new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date(t));}double[] parseGeo(String s){try{if(s==null||!s.startsWith("geo:"))return null;String[] a=s.substring(4).split("\\?")[0].split(",");return new double[]{Double.parseDouble(a[0]),Double.parseDouble(a[1])};}catch(Exception e){return null;}}String js(String x){return x.replace("\\","\\\\").replace("'","\\'");}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
